window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[268]={"id":"268","numero":268,"titre":"Calcémie","objectifs":[{"id":"268-1","rang":"A","rubrique":"Définition","titre":"Connaître les normes de la calcémie totale et de la calcémie ionisée","contenu":"<div class=\"callout callout-info\">\n        <strong><span class=\"kw-clinique\">Les</span> deux normes à connaître.</strong> <span class=\"kw-bio\">Calcémie</span> <span class=\"kw-def\">totale</span> normale entre <span class=\"kw-chiffre\">2,20 et 2,60 mmol/L</span> (≈<span class=\"kw-chiffre\"> 105 mg/L</span>) · <span class=\"kw-bio\">Calcémie</span> <span class=\"kw-def\">ionisée</span> normale entre <span class=\"kw-chiffre\">1,15 et 1,35 mmol/L</span>. Seul le <span class=\"kw-bio\">calcium ionisé</span> est la fraction métaboliquement active et la <strong>seule variable régulée</strong>.\n      </div>\n      <p style=\"margin: 0 0 6px; font-size: 13px;\"><strong>Composition de la <span class=\"kw-bio\">calcémie</span> totale :</strong></p>\n      <table >\n        <thead><tr><th>Fraction</th><th>Part · caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Calcium ionisé</strong></span></td>\n            <td><span class=\"kw-chiffre\">50–55 %</span> — fraction métaboliquement active, soumise à une régulation stricte (dosage de référence)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Calcium lié aux protéines</strong></span></td>\n            <td><span class=\"kw-chiffre\">≈ 40 %</span> — principalement à l'<span class=\"kw-clinique\">albumine</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Calcium complexé aux anions</strong></span></td>\n            <td><span class=\"kw-chiffre\">5–10 %</span> — citrates, phosphates, <span class=\"kw-bio\">bicarbonates</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong><span class=\"kw-bio\">Calcémie</span> ionisée — facteurs de variation :</strong></p>\n      <table >\n        <thead><tr><th>Mesure / facteur</th><th>Effet</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Dosage</strong></span></td>\n            <td>Référence mais difficile : prélèvement sur <span class=\"kw-clinique\">seringue à gaz du sang</span>, envoi <span class=\"kw-clinique\">immédiat à 4 °C</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>pH sanguin</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Acidose</span> : augmente le calcium ionisé (↓ fraction liée à l'<span class=\"kw-bio\">albumine</span>)</li>\n                <li><span class=\"kw-etio\">Alcalose</span> : diminue le calcium ionisé (↑ fraction liée à l'<span class=\"kw-bio\">albumine</span>)</li>\n                <li><strong>Le <span class=\"kw-bio\">pH</span> ne modifie PAS le calcium total</strong> <span class=\"kw-ci\">❌</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong>Distribution, sources et capteur du calcium :</strong></p>\n      <table >\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Distribution</strong></span></td><td>Calcium majoritairement contenu dans le compartiment osseux (<span class=\"kw-chiffre\">99 %</span>)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Sources sanguines</strong></span></td><td>Deux sources : tube digestif (≈<span class=\"kw-chiffre\"> 1 g</span>/j) et os</td></tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>CaSR</strong></span></td>\n            <td>\n              Récepteur sensible au calcium, stimulé par l'↑ du <span class=\"kw-bio\">calcium ionisé</span> :\n              <ul>\n                <li>Cellules parathyroïdiennes : freine la sécrétion de <span class=\"kw-bio\">PTH</span></li>\n                <li>Cellules rénales : inhibe la réabsorption rénale du calcium → <span class=\"kw-clinique\">↑ calciurie</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"268-2","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier une hypercalcémie","contenu":"<table >\n        <thead><tr><th>Définition <span class=\"kw-ttt\">biologique</span></th><th>Seuils</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Calcémie totale</strong></span> (corrigée si besoin)</td><td><span class=\"kw-alerte\">&gt; 2,60 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Calcémie ionisée</strong></span></td><td><span class=\"kw-alerte\">&gt; 1,35 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Selon contexte d'urgence</strong></span></td><td>Ca totale &gt;<span class=\"kw-chiffre\"> 2,55 mmol/L</span>, ou Ca ionisée &gt;<span class=\"kw-chiffre\"> 1,30 mmol/L</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Hypercalcémie vraie.</strong> Élévation du <span class=\"kw-bio\">calcium ionisé</span> — la seule variable régulée.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Fausse hypercalcémie</strong> = augmentation de la fraction liée aux protéines (&gt;<span class=\"kw-chiffre\"> 40 %</span> du calcium sérique est lié à l'<span class=\"kw-bio\">albumine</span>).\n        <ul>\n          <li><span class=\"kw-etio\">Hyperalbuminémie</span> (<span class=\"kw-clinique\">déshydratation</span>) : ↑ calcium <span class=\"kw-clinique\">total</span> mais calcium ionisé <span class=\"kw-clinique\">normal</span> <span class=\"kw-ci\">⚠️</span></li>\n          <li>À l'inverse, une <span class=\"kw-etio\">hypoalbuminémie</span> peut <strong>masquer</strong> une hypercalcémie <span class=\"kw-ci\">⚠️</span></li>\n        </ul>\n      </div>\n      <table >\n        <thead><tr><th><span class=\"kw-bio\">Calcémie</span> corrigée</th><th>Formule</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Correction sur l'albumine</strong></span></td>\n            <td>Ca corrigée (mmol/L) = Ca total mesuré + <span class=\"kw-chiffre\">[(40 − albuminémie) × 0,025]</span><br><span class=\"muted\">(albuminémie en g/L ; valeur de référence <span class=\"kw-chiffre\">40 g/L</span>)</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Dogme.</strong> Tout bilan d'hyper- ou d'hypocalcémie doit comporter un dosage du <span class=\"kw-bio\">calcium ionisé</span> et/ou un <span class=\"kw-clinique\">dosage d'albumine</span> (± <span class=\"kw-bio\">pH</span> sanguin pour ajuster le calcium ionisé).\n      </div>","frequence":3},{"id":"268-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux mécanismes des hypercalcémies","contenu":"<div class=\"callout callout-info\">\n        <strong>Principe.</strong> Une hypercalcémie survient lorsque <span class=\"kw-chiffre\">l'entrée de calcium dans le sang</span> (os + tube digestif) <span class=\"kw-chiffre\">excède les sorties</span> (urinaires et osseuses).\n      </div>\n      <p style=\"margin: 0 0 6px; font-size: 13px;\"><strong>Trois grands mécanismes d'entrée :</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Exemples d'étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Excès de résorption osseuse</strong></span><br><span class=\"muted\">(le plus fréquent)</span></td>\n            <td>Métastases ostéolytiques, myélome, hyperparathyroïdie, hyperthyroïdie, immobilisation prolongée, hypervitaminose A</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Excès d'absorption digestive</strong></span></td>\n            <td>Hypervitaminose D, granulomatoses (1α-hydroxylase <span class=\"kw-clinique\">non régulée</span> → ↑ calcitriol), syndrome des buveurs de lait / excès d'apport calcique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Excès de réabsorption rénale</strong></span></td>\n            <td>Hyperparathyroïdie primaire, <span class=\"kw-ttt\">diurétiques</span> thiazidiques, hypercalcémie-hypocalciurie familiale bénigne</td>\n          </tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong>Rappel — <span class=\"kw-clinique\">les</span> deux hormones de la régulation calcique :</strong></p>\n      <table >\n        <thead><tr><th>Hormone</th><th>Effets</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>PTH</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Os</span> : ↑ résorption osseuse (libère Ca + phosphate)</li>\n                <li><span class=\"kw-clinique\">Rein</span> : ↑ réabsorption du calcium (anse de Henle, TCD) ; <strong>↓</strong> réabsorption du phosphate (tube proximal) ; ↑ activation de la <span class=\"kw-bio\">vitamine D</span></li>\n                <li>Bilan : <span class=\"kw-clinique\">↑ calcémie</span>, <span class=\"kw-clinique\">↓ phosphorémie</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Vitamine D active</strong></span><br>(calcitriol)</td>\n            <td><span class=\"kw-clinique\">Intestin</span> : ↑ absorption du calcium et du phosphore · <span class=\"kw-clinique\">Rein</span> : ↑ réabsorption Ca et P → <span class=\"kw-clinique\">↑ calcémie</span>, <span class=\"kw-clinique\">↑ phosphorémie</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Réflexe-clé.</strong> En cas d'hypercalcémie, la <span class=\"kw-clinique\">PTH est normalement freinée</span> (via le CaSR). Une <span class=\"kw-bio\">PTH</span> élevée ou « normale » (donc <span class=\"kw-clinique\">inadaptée</span>) oriente d'emblée vers une hyperparathyroïdie — c'est le pivot de l'arbre diagnostique.\n      </div>","frequence":1},{"id":"268-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux signes cliniques associés à l'hypercalcémie","contenu":"<div class=\"callout callout-info\">\n        <strong>Préambule.</strong> Expression clinique <span class=\"kw-clinique\">très variable</span>, dépendant de la <span class=\"kw-clinique\">sévérité</span> et de la <span class=\"kw-clinique\">rapidité d'installation</span>. Une part importante des hypercalcémies est <span class=\"kw-clinique\">asymptomatique</span> (≈<span class=\"kw-chiffre\"> 10 %</span> selon le Collège de néphrologie, jusqu'à<span class=\"kw-chiffre\"> 40 %</span> selon la rhumatologie). Tableau <span class=\"kw-alerte\">aspécifique</span>, souvent trompeur par sa présentation digestive.\n      </div>\n      <div class=\"callout callout-danger\">\n        <strong>🔥 Crise aiguë hypercalcémique / hypercalcémie sévère</strong> — <span class=\"kw-alerte\">urgence</span> médicale, <span class=\"kw-alerte\">risque de décès par trouble du rythme</span>.\n        <ul>\n          <li><strong>Généraux :</strong> <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">anorexie</span></li>\n          <li><strong>Digestifs :</strong> douleurs abdominales (parfois pseudo-chirurgicales : occlusion, contracture), <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">nausées</span>, vomissements ; rares <span class=\"kw-clinique\">pancréatites aiguës</span></li>\n          <li><strong>Neurologiques :</strong> troubles de la vigilance (du <span class=\"kw-clinique\">syndrome confusionnel</span> au <span class=\"kw-alerte\">coma</span>), déficits cognitifs, troubles de l'humeur, épisodes hallucinatoires / psychotiques</li>\n          <li><strong>Rénaux :</strong> <span class=\"kw-clinique\">déshydratation inexpliquée</span> par perte rénale de Na et d'eau — syndrome polyuro-polydipsique (<span class=\"kw-clinique\">diabète insipide néphrogénique</span>, perte des aquaporines 2), DEC ± <span class=\"kw-alerte\">IRA fonctionnelle</span></li>\n          <li><strong>Cardiovasculaires :</strong> <span class=\"kw-etio\">HTA</span>, ou <span class=\"kw-clinique\">hypotension</span> si <span class=\"kw-clinique\">déshydratation</span> majeure ; anomalies <span class=\"kw-imagerie\">ECG</span> ; troubles du rythme (ESV, <span class=\"kw-alerte\">TV</span>, <span class=\"kw-alerte\">FV</span>) si Ca &gt;<span class=\"kw-chiffre\"> 3,5–4 mmol/L</span></li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Cercle vicieux rénal.</strong> Activation du <span class=\"kw-def\">CaSR</span> rénal → <span class=\"kw-clinique\">inhibition de NKCC</span> (anse de Henle) → natriurèse → <span class=\"kw-clinique\">déshydratation</span> extracellulaire → <span class=\"kw-alerte\">IRA fonctionnelle</span> qui, en limitant <span class=\"kw-clinique\">les</span> sorties rénales de calcium, <strong>amplifie l'hypercalcémie</strong>.\n      </div>\n      <div class=\"callout callout-danger\">\n        <strong>Digitaliques formellement <span class=\"kw-ci\">contre-indiqués</span></strong> en cas d'hypercalcémie (ils favorisent <span class=\"kw-clinique\">les</span> troubles du rythme) <span class=\"kw-ci\">⚠️</span>\n      </div>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong>Hypercalcémie chronique :</strong></p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Généraux</strong></span></td><td><span class=\"kw-clinique\">Asthénie</span> physique/psychique, <span class=\"kw-clinique\">amaigrissement</span>, anorexie</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Digestifs</strong></span></td><td><span class=\"kw-clinique\">Épigastralgies</span>, <span class=\"kw-clinique\">nausées</span>, vomissements (parfois incoercibles), constipation</td></tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Rénaux</strong></span></td>\n            <td>\n              <ul>\n                <li>Syndrome polyuro-polydipsique (<span class=\"kw-etio\">diabète</span> insipide néphrogénique, ≈<span class=\"kw-chiffre\"> 20 %</span>)</li>\n                <li><span class=\"kw-clinique\">Néphrocalcinose</span> (hypercalciurie prolongée, dépôts tubulo-interstitiels) → IRC</li>\n                <li><span class=\"kw-clinique\">Lithiases</span> (phosphate / oxalate de calcium), souvent bilatérales et récidivantes</li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Neurologiques</strong></span></td><td><span class=\"kw-clinique\">Céphalées</span>, syndrome « pseudo-polynévritique » (hypo/aréflexie), allure « pseudo-myopathique », troubles cognitifs et de la mémoire</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Psychiatriques</strong></span></td><td>Troubles de l'humeur, dépression / anxiété, épisodes hallucinatoires ou psychotiques</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Cardiovasculaires</strong></span></td><td><span class=\"kw-etio\">HTA</span>, anomalies <span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-clinique\">calcifications ectopiques</span> (coronaires, valves, fibres myocardiques)</td></tr>\n        </tbody>\n      </table>","frequence":3},{"id":"268-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principales anomalies ECG associées à l'hypercalcémie","contenu":"<div class=\"callout callout-info\">\n        <strong>Moyen mnémotechnique :</strong> « <em>ta <span class=\"kw-clinique\">RaQueTTe</span> <span class=\"kw-clinique\">plate</span> perd son rythme</em> ».\n      </div>\n      <table >\n        <thead><tr><th>Mnémo</th><th>Anomalie <span class=\"kw-imagerie\">ECG</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>TA</strong></td><td><span class=\"kw-clinique\">Tachycardie</span></td></tr>\n          <tr><td><strong>Ra<span class=\"kw-clinique\">Q</span>ue<span class=\"kw-clinique\">T</span></strong></td><td><span class=\"kw-clinique\">Raccourcissement du QT</span> ⭐ (signe le plus caractéristique)</td></tr>\n          <tr><td><strong>Pla<span class=\"kw-clinique\">T</span>e</strong></td><td><span class=\"kw-clinique\">Aplatissement de l'onde T</span></td></tr>\n          <tr><td><strong>Pe<span class=\"kw-clinique\">R</span>d</strong></td><td><span class=\"kw-clinique\">Allongement du PR</span> — troubles de conduction possibles : <span class=\"kw-clinique\">bradycardie</span>, BSA, BAV, élargissement des QRS</td></tr>\n          <tr><td><strong>son <span class=\"kw-clinique\">R</span>ythme</strong></td><td><span class=\"kw-alerte\">Troubles du rythme</span> (ESV, <span class=\"kw-alerte\">TV</span>, <span class=\"kw-alerte\">FV</span>) en cas d'hypercalcémie majeure (&gt;<span class=\"kw-chiffre\"> 3,5–4 mmol/L</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Digitaliques formellement <span class=\"kw-ci\">contre-indiqués</span></strong> (potentialisent la toxicité cardiaque de l'hypercalcémie) <span class=\"kw-ci\">⚠️</span>\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Indication.</strong> <span class=\"kw-imagerie\">ECG</span> à réaliser <span class=\"kw-clinique\">systématiquement</span> devant une hypercalcémie sévère (<span class=\"kw-chiffre\">&gt; 3 mmol/L</span>).\n      </div>","frequence":1,"liens":[{"href":"https://www.e-cardiogram.com/hypercalcemie/","label":"ECG — Hypercalcémie (e-cardiogram)"}]},{"id":"268-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires de première intention à réaliser en fonction du contexte devant une hypercalcémie","contenu":"<p style=\"margin: 0 0 8px; font-size: 13px;\">Le bilan de <span class=\"kw-chiffre\">première intention</span> répond à trois questions : <strong>confirmer</strong>, <strong>évaluer la gravité</strong>, <strong>orienter l'étiologie</strong>.</p>\n      <h4 style=\"margin: 0 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\">1. <span class=\"kw-def\">Diagnostic positif</span></h4>\n      <ul>\n        <li><span class=\"kw-bio\">Calcium total</span></li>\n        <li><span class=\"kw-bio\">Calcium ionisé</span> et/ou <span class=\"kw-bio\">albuminémie</span> (± <span class=\"kw-bio\">pH sanguin</span> pour ajuster le calcium ionisé)</li>\n      </ul>\n      <h4 style=\"margin: 14px 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\">2. Évaluation de la gravité</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Créatinine</span>, <span class=\"kw-bio\">ionogramme</span> sanguin</li>\n        <li><span class=\"kw-bio\">ECG</span> — systématique devant une hypercalcémie sévère (<span class=\"kw-chiffre\">&gt; 3 mmol/L</span>)</li>\n      </ul>\n      <h4 style=\"margin: 14px 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\">3. Orientation étiologique (1ʳᵉ intention)</h4>\n      <table >\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>PTH plasmatique</strong></span> ⭐</td><td><strong>Examen central</strong> de l'arbre diagnostique — normalement <span class=\"kw-clinique\">freinée</span> en cas d'hypercalcémie</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Phosphate sérique</strong></span></td><td>Aide à classer (basse dans HPT primaire et HHM)</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Vitamine D</strong></span></td><td>25-OH-vitamine D et calcitriolémie (1,25-OH-vitamine D)</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Calciurie</strong></span></td><td>À jeun et des <span class=\"kw-chiffre\">24 h</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>EPP</strong></span></td><td><span class=\"kw-bio\">Électrophorèse des protéines</span> plasmatiques — systématique selon le Collège de néphrologie ⭐</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Logique de lecture.</strong> La <span class=\"kw-clinique\">PTH</span> dichotomise d'emblée : <strong><span class=\"kw-bio\">PTH</span> élevée / inadaptée</strong> → hyperparathyroïdie et apparentés ; <strong><span class=\"kw-bio\">PTH</span> basse / freinée</strong> → cancers, granulomatoses, intoxications (cf. objectif Étiologies).\n      </div>","frequence":4},{"id":"268-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires utiles au diagnostic étiologique des hypercalcémies en fonction du bilan initial","contenu":"<div class=\"callout callout-info\">\n        <strong>Stratégie.</strong> <span class=\"kw-clinique\">Les</span> examens de 2ᵉ intention sont guidés par le résultat de la <span class=\"kw-bio\">PTH</span> et de la <span class=\"kw-clinique\">phosphatémie</span> du bilan initial.\n      </div>\n      <p style=\"margin: 0 0 6px; font-size: 13px;\"><strong>Signature <span class=\"kw-ttt\">biologique</span> des principales causes</strong> (lecture en fonction du bilan initial) :</p>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th><span class=\"kw-bio\">PTH</span></th><th>Phosphate</th><th>Calcitriol</th><th>Calciurie</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">HPT primaire / tertiaire</span></td><td>Inadaptée</td><td>Basse</td><td>Élevé</td><td>Élevée</td></tr>\n          <tr><td><span class=\"kw-etio\">Hypercalcémie-hypocalciurie familiale</span></td><td>Inadaptée</td><td>Basse</td><td>Élevé</td><td><span class=\"kw-clinique\">Basse</span> ⭐</td></tr>\n          <tr><td><span class=\"kw-etio\">Hypercalcémie humorale maligne</span></td><td>Basse</td><td>Basse</td><td><span class=\"kw-clinique\">Bas</span> ⭐</td><td>Élevée</td></tr>\n          <tr><td><span class=\"kw-etio\">Hypercalcémie osseuse (métastases)</span></td><td>Basse</td><td>Normale / ↑</td><td>Normal</td><td>Très élevée</td></tr>\n          <tr><td><span class=\"kw-etio\">Intoxication / excès de vitamine D</span></td><td>Basse</td><td>Élevée</td><td>Élevé</td><td>Élevée</td></tr>\n        </tbody>\n      </table>\n      <p style=\"margin: 12px 0 6px; font-size: 13px;\"><strong>Examens de 2ᵉ intention selon l'orientation :</strong></p>\n      <table >\n        <thead><tr><th>Orientation</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>PTH inadaptée</strong></span></td>\n            <td>Confirmer l'hyperparathyroïdie ; imagerie de localisation de l'adénome : <span class=\"kw-imagerie\">échographie cervicale</span>, <span class=\"kw-imagerie\">scintigraphie au sesta-MIBI</span>, voire <span class=\"kw-imagerie\">PET-scan à la choline</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>PTH basse / freinée</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">NFS, CRP</span></li>\n                <li><span class=\"kw-bio\">TSHus</span> (hyperthyroïdie)</li>\n                <li><span class=\"kw-bio\">Enzyme de conversion de l'angiotensine</span> (granulomatose)</li>\n                <li><span class=\"kw-bio\">EPS, EPU</span>, <span class=\"kw-bio\">protéinurie</span> (myélome)</li>\n                <li><span class=\"kw-imagerie\">Radiographie de thorax</span></li>\n                <li><span class=\"kw-bio\">PTHrp</span> — dosage difficile, réalisé en cas d'hypophosphatémie associée (hypercalcémie humorale maligne)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":2},{"id":"268-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des hypercalcémies (arbre diagnostique)","contenu":"<div class=\"callout callout-danger\">\n        <strong>À retenir avant tout.</strong> L'<span class=\"kw-etio\">hyperparathyroïdie primaire</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">hypercalcémies des cancers</span> représentent à elles seules <span class=\"kw-chiffre\">≈ 90 %</span> des étiologies. La <span class=\"kw-clinique\">PTH</span> est la première branche de l'arbre.\n      </div>\n\n      <h4 style=\"margin: 0 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\">Branche 1 — Hypercalcémie à <span class=\"kw-bio\">PTH</span> élevée / inadaptée</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Repères</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Hyperparathyroïdie primaire</strong></span></td><td><span class=\"kw-chiffre\">55–60 %</span> des hypercalcémies — cause n° 1 ⭐ (cf. focus ci-dessous)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Hyperparathyroïdie tertiaire</strong></span></td><td>Autonomisation d'une HPT secondaire, surtout sur <span class=\"kw-clinique\">insuffisance rénale chronique</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Lithium</strong></span></td><td>Action directe sur <span class=\"kw-clinique\">les</span> parathyroïdes (≈<span class=\"kw-chiffre\"> 10 %</span> des patients traités, réversible à l'arrêt)</td></tr>\n          <tr><td><span class=\"kw-ci\"><strong>Hypercalcémie-hypocalciurie familiale bénigne — à distinguer</strong></span></td><td>Autosomique dominante, généralement asymptomatique ; tableau <span class=\"kw-ttt\">biologique</span> d'HPT primaire <strong>sauf la calciurie BASSE</strong> ⭐ (mutation inactivatrice du CaSR)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 16px 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\">Branche 2 — Hypercalcémie à <span class=\"kw-bio\">PTH</span> basse / freinée</h4>\n      <table >\n        <thead><tr><th>Famille</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Néoplasies (≈ 30 %)</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Métastases osseuses</span> ostéolytiques — <strong>PPRST</strong> : prostate, poumon, rein, sein, thyroïde</li>\n                <li><span class=\"kw-etio\">Myélome multiple</span> (Osteoclast Activating Factor) ; lymphomes, leucémies</li>\n                <li><span class=\"kw-etio\">Hypercalcémie humorale maligne</span> : sécrétion <span class=\"kw-etio\">paranéoplasique</span> de <strong>PTHrp</strong> (<span class=\"kw-clinique\">carcinome</span> pulmonaire non à petites cellules, LNH à cellules T/HTLV1…) — <span class=\"kw-bio\">PTH</span> effondrée, <strong>calcitriol bas</strong> ⭐</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Médicaments</strong></span></td>\n            <td>Hypervitaminose D ; hypervitaminose A (<span class=\"kw-ttt\">rétinoïdes</span>, &gt; 50 <span class=\"kw-chiffre\">000 UI</span>/j) ; <span class=\"kw-ttt\">diurétiques</span> <span class=\"kw-ttt\">thiazidiques</span> ; tériparatide ; (SERM, tamoxifène, théophylline, foscarnet)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Endocriniennes</strong></span> ⭐</td>\n            <td>Hyperthyroïdie (<span class=\"kw-chiffre\">15–20 %</span>), insuffisance surrénalienne aiguë, phéochromocytome (après ablation), acromégalie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Granulomatoses</strong></span></td>\n            <td>1α-hydroxylase non régulée → ↑ calcitriol : <span class=\"kw-etio\">sarcoïdose</span> (<span class=\"kw-chiffre\">10–20 %</span>) ++, <span class=\"kw-etio\">tuberculose</span> ++, lèpre, histoplasmose, bérylliose…</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Autres</strong></span></td>\n            <td>Syndrome des buveurs de lait / excès de supplémentation calcique (surtout si <span class=\"kw-ci\">insuffisance rénale</span>) ; immobilisation prolongée complète ; correction de rhabdomyolyse</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\" style=\"border-left: 3px solid var(--mat);\">\n        <strong>Focus — Hyperparathyroïdie primaire (cause n° 1).</strong>\n        <ul>\n          <li><strong><span class=\"kw-def\">Terrain</span> :</strong> endocrinopathie fréquente de la <span class=\"kw-clinique\">femme ménopausée</span> (<span class=\"kw-chiffre\">50–60 ans</span>), <span class=\"kw-def\">prévalence</span> ≈<span class=\"kw-chiffre\"> 1 %</span></li>\n          <li><strong>Clinique :</strong> <span class=\"kw-clinique\">asymptomatique dans 80–90 %</span> des cas ⭐ ; sinon manifestations d'hypercalcémie, osseuses (ostéoporose, ostéite fibrokystique exceptionnelle) et extra-osseuses (lithiase, néphrocalcinose, chondrocalcinose)</li>\n          <li><strong>Biologie :</strong> hypercalcémie + <span class=\"kw-clinique\">PTH inadaptée</span> (élevée ou normale) ⭐ ; hypophosphatémie (2/3) ; hypercalciurie ; hypercalcitriolémie</li>\n          <li><strong>Étiologies :</strong> adénome unique (≈<span class=\"kw-chiffre\"> 80 %</span>), hyperplasie des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>landes (<span class=\"kw-chiffre\">10–15 %</span> — penser <span class=\"kw-clinique\">NEM 1 / NEM 2</span> si sujet jeune ou familial), <span class=\"kw-clinique\">carcinome</span> parathyroïdien (&lt;<span class=\"kw-chiffre\"> 2 %</span>, hypercalcémie sévère)</li>\n          <li><strong>Indications chirurgicales :</strong> forme symptomatique ; âge <span class=\"kw-chiffre\">&lt; 50 ans</span> ; Ca <span class=\"kw-chiffre\">&gt; 2,75 mmol/L</span> ou calciurie <span class=\"kw-chiffre\">&gt; 10 mmol/24 h</span> ; <span class=\"kw-ci\">insuffisance rénale</span> attribuable ; atteinte osseuse (<span class=\"kw-chiffre\">T-score &lt; −2,5</span>)</li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin: 16px 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\">Hypercalcémies d'origine osseuse (à part)</h4>\n      <ul>\n        <li>Métastases ostéolytiques (sein, poumon, rein), myélome multiple</li>\n        <li>Hyperthyroïdie, immobilisation prolongée, maladie de Paget (si immobilisation associée)</li>\n        <li>Hypervitaminose A (acide rétinoïque ↑ la résorption osseuse)</li>\n      </ul>","frequence":6,"liens":[{"href":"https://radiopaedia.org/articles/hyperparathyroidism","label":"Radiopaedia — Hyperparathyroidism"}]},{"id":"268-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement des hypercalcémies sévères","contenu":"<div class=\"callout callout-danger\">\n        <strong>🔥 Hypercalcémie aiguë sévère symptomatique (&gt;<span class=\"kw-chiffre\"> 3 mmol/L</span>) = <span class=\"kw-alerte\">urgence</span> thérapeutique.</strong> Objectif : <span class=\"kw-clinique\">faire baisser la calcémie</span>, puis traitement étiologique. <span class=\"kw-def\">Surveillance</span> en <span class=\"kw-clinique\">USC / réanimation</span><span class=\"kw-chiffre\"> 24–48 h</span> (fonction rénale, <span class=\"kw-bio\">ionogramme</span>, calcium ionisé, <span class=\"kw-imagerie\">ECG</span> quotidien).\n      </div>\n\n      <h4 style=\"margin: 0 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\">Mesures immédiates</h4>\n      <table >\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Arrêt des traitements à risque</strong></span></td>\n            <td>\n              <ul>\n                <li>Hypercalcémiants : <span class=\"kw-ttt\">calcium</span>, <span class=\"kw-ttt\">vitamine D</span>, <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">thiazidiques</span></li>\n                <li>Aggravant la <span class=\"kw-clinique\">déshydratation</span> : <span class=\"kw-ttt\">diurétiques</span>, néphrotoxiques</li>\n                <li>Aggravant la toxicité cardiaque : <span class=\"kw-ci\">digitaliques</span>, hypokaliémiants</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>1ʳᵉ intention — Réhydratation</strong></span></td>\n            <td>Sérum salé isotonique <span class=\"kw-chiffre\">0,9 %</span> (ex. <span class=\"kw-chiffre\">1 L la 1ʳᵉ heure puis 2–4 L/24 h</span>) — corr<span class=\"kw-chiffre\">ige</span> la DEC et effet <span class=\"kw-clinique\">pro-calciuriant</span> (la réplétion volémique ↓ la réabsorption rénale du calcium)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin: 14px 0 8px; font-size: 13.5px; border-left: 3px solid var(--mat); padding-left: 8px;\">Traitement selon le mécanisme</h4>\n      <table >\n        <thead><tr><th>Cible</th><th>Moyen · indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>↓ Résorption osseuse</strong></span> ++</td>\n            <td><span class=\"kw-ttt\">Bisphosphonates</span> (dose selon sévérité ; <span class=\"kw-clinique\">effet retardé, dès 48 h</span>) ; <span class=\"kw-ttt\">dénosumab</span> si échec ou CI — hypercalcémie maligne, HPT primaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>↓ Absorption digestive</strong></span></td>\n            <td><span class=\"kw-ttt\">Glucocorticoïdes</span> (<span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">10–20 mg</span>/j) — myélome, hémopathies (lymphome), granulomatoses (<span class=\"kw-clinique\">sarcoïdose</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Spécifique</strong></span></td>\n            <td><span class=\"kw-ttt\">Cinacalcet</span> (calcimimétique) — hypercalcémie sévère du <span class=\"kw-etio\">carcinome parathyroïdien</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Formes graves 🔥</strong></span></td>\n            <td><span class=\"kw-ttt\">Épuration extra-rénale</span> (dialyse, bain pauvre en calcium) — surtout si <span class=\"kw-ci\">insuffisance rénale</span> ; intérêt = <span class=\"kw-clinique\">effet rapide</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Ne sont plus recommandés <span class=\"kw-ci\">❌</span> :</strong>\n        <ul>\n          <li><span class=\"kw-ttt\">Calcitonine</span> — effet trop transitoire</li>\n          <li><span class=\"kw-ttt\">Diurèse forcée au furosémide</span> — déconseillée (notamment dans le myélome) ; éventuellement après réhydratation pour maintenir la diurèse en cas d'IRA fonctionnelle / <span class=\"kw-ci\">insuffisance cardiaque</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Traitement étiologique</strong> (en parallèle) : arrêt d'une intoxication vitaminique, traitement d'un cancer ou d'une endocrinopathie, <span class=\"kw-ttt\">exérèse</span> d'un adénome parathyroïdien, remobilisation.\n      </div>","frequence":4,"liens":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/39.%20Hypercalc%C3%A9mie%20aigu%C3%AB%20s%C3%A9v%C3%A8re.pdf","label":"CEMIR — Hypercalcémie aiguë sévère (PDF)"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Hypercalcémie aiguë sévère <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> thérapeutique</span></strong></p><p><span class=\"kw-ttt\">Réhydratation</span> par <span class=\"kw-ttt\">sérum salé isotonique 0,9 %</span> sans délai (<span class=\"kw-chiffre\">1 L la 1ʳᵉ heure puis 2–4 L/24 h</span>)</p><ul><li><span class=\"kw-alerte\">Ca &gt; 3,5 mmol/L</span>, ou <span class=\"kw-chiffre\">&gt; 3 mmol/L</span> avec <span class=\"kw-alerte\">signes de mauvaise tolérance</span></li><li>Risque de <span class=\"kw-alerte\">décès par trouble du rythme cardiaque</span></li><li>Majorité des hypercalcémies <span class=\"kw-chiffre\">&lt; 3 mmol/L</span> = peu ou pas symptomatiques (le <span class=\"kw-clinique\">traitement étiologique</span> suffit)</li></ul><p><strong>Délais d’action des traitements</strong></p><ul><li><span class=\"kw-ttt\">Réhydratation</span> : effet <span class=\"kw-clinique\">pro-calciuriant</span> rapide (1ʳᵉ intention)</li><li><span class=\"kw-ttt\">Bisphosphonates</span> : effet <span class=\"kw-clinique\">retardé</span>, dès <span class=\"kw-chiffre\">48 h</span></li><li><span class=\"kw-ttt\">Épuration extra-rénale</span> : effet <span class=\"kw-clinique\">rapide</span> — forme grave avec <span class=\"kw-clinique\">insuffisance rénale</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> hypercalcémie <span class=\"kw-chiffre\">&lt; 3 mmol/L</span> peu/pas symptomatique → <span class=\"kw-clinique\">traitement étiologique</span> suffit.<br><strong>USC / <span class=\"kw-alerte\">réanimation</span> :</strong> hypercalcémie <span class=\"kw-clinique\">aiguë sévère symptomatique</span> (<span class=\"kw-chiffre\">&gt; 3 mmol/L</span>) → <span class=\"kw-def\">surveillance</span> rapprochée <span class=\"kw-chiffre\">24–48 h</span>.<br><strong>HPT primaire asymptomatique :</strong> <span class=\"kw-clinique\">simple surveillance</span> possible en l’absence d’indication chirurgicale.<br><strong><span class=\"kw-ttt\">Chirurgie</span> spécialisée :</strong> <span class=\"kw-ttt\">exérèse de l’adénome parathyroïdien</span> si HPT primaire symptomatique, <span class=\"kw-chiffre\">âge &lt; 50 ans</span>, Ca <span class=\"kw-chiffre\">&gt; 2,75 mmol/L</span>, calciurie <span class=\"kw-chiffre\">&gt; 10 mmol/24 h</span>, <span class=\"kw-ci\">insuffisance rénale</span> attribuable ou atteinte osseuse (<span class=\"kw-chiffre\">T-score &lt; −2,5</span>).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Calcémie &gt; 3,5 mmol/L</span> (ou <span class=\"kw-chiffre\">&gt; 3 mmol/L</span> avec signes de mauvaise tolérance)</li><li><span class=\"kw-alerte\">Troubles de la vigilance</span> : du <span class=\"kw-clinique\">syndrome confusionnel</span> au <span class=\"kw-alerte\">coma</span></li><li><span class=\"kw-alerte\">Troubles du rythme</span> (ESV, <span class=\"kw-alerte\">TV</span>, <span class=\"kw-alerte\">FV</span>) si Ca <span class=\"kw-chiffre\">&gt; 3,5–4 mmol/L</span> ; <span class=\"kw-clinique\">raccourcissement du QT</span> à l’<span class=\"kw-imagerie\">ECG</span></li><li><span class=\"kw-clinique\">Déshydratation extracellulaire</span> ± <span class=\"kw-alerte\">insuffisance rénale aiguë fonctionnelle</span> (cercle vicieux qui amplifie l’hypercalcémie)</li><li>Douleurs abdominales <span class=\"kw-clinique\">pseudo-chirurgicales</span> ; rares <span class=\"kw-clinique\">pancréatites aiguës</span></li><li><span class=\"kw-etio\">Carcinome parathyroïdien</span> : hypercalcémie sévère (<span class=\"kw-chiffre\">&gt; 3,5 mmol/L</span>) mal tolérée</li><li><span class=\"kw-ci\">Digitaliques contre-indiqués</span> (potentialisent la toxicité cardiaque)</li></ul>","principes":"<p><strong>Règle d’or :</strong> d’abord <span class=\"kw-clinique\">faire baisser la calcémie</span>, puis <span class=\"kw-clinique\">traitement étiologique</span>. Une hypercalcémie <span class=\"kw-chiffre\">&lt; 3 mmol/L</span> peu symptomatique relève surtout du traitement de la cause.</p><p><strong>Mesures immédiates</strong></p><ul><li>Arrêt des traitements <span class=\"kw-ttt\">hypercalcémiants</span> : <span class=\"kw-ttt\">calcium</span>, <span class=\"kw-ttt\">vitamine D</span>, <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">thiazidiques</span></li><li>Arrêt des <span class=\"kw-ttt\">néphrotoxiques</span> et des <span class=\"kw-ci\">digitaliques</span> / hypokaliémiants</li><li><span class=\"kw-chiffre\">1ʳᵉ intention</span> : <span class=\"kw-ttt\">réhydratation</span> par <span class=\"kw-ttt\">sérum salé isotonique 0,9 %</span> (effet <span class=\"kw-clinique\">pro-calciuriant</span>)</li></ul><p><strong>Traitement selon le mécanisme</strong></p><ul><li>↓ Résorption osseuse ++ : <span class=\"kw-ttt\">bisphosphonates</span> (effet dès <span class=\"kw-chiffre\">48 h</span>) ; <span class=\"kw-ttt\">dénosumab</span> si échec ou CI — hypercalcémie maligne, HPT primaire</li><li>↓ Absorption digestive : <span class=\"kw-ttt\">glucocorticoïdes</span> (<span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">10–20 mg/j</span>) — myélome, hémopathies, granulomatoses</li><li>Spécifique : <span class=\"kw-ttt\">cinacalcet</span> (calcimimétique) — <span class=\"kw-etio\">carcinome parathyroïdien</span></li><li>Forme grave : <span class=\"kw-ttt\">épuration extra-rénale</span> (bain pauvre en calcium) si <span class=\"kw-clinique\">insuffisance rénale</span></li></ul><p><strong>Ne sont plus recommandés</strong></p><ul><li><span class=\"kw-ttt\">Calcitonine</span> — effet trop transitoire</li><li><span class=\"kw-ttt\">Diurèse forcée au furosémide</span> — déconseillée (myélome) ; éventuellement après réhydratation pour maintenir la diurèse (IRA fonctionnelle / <span class=\"kw-ci\">insuffisance cardiaque</span>)</li></ul><p><strong>Traitement étiologique <span class=\"q\">— en parallèle</span></strong></p><ul><li>Arrêt d’une <span class=\"kw-etio\">intoxication vitaminique</span></li><li>Traitement d’un <span class=\"kw-etio\">cancer</span> ou d’une <span class=\"kw-etio\">endocrinopathie</span></li><li><span class=\"kw-ttt\">Exérèse d’un adénome parathyroïdien</span> ; <span class=\"kw-clinique\">remobilisation</span></li></ul>","suivi":"<p><strong>Hypercalcémie aiguë sévère :</strong> <span class=\"kw-def\">surveillance</span> en <span class=\"kw-clinique\">USC / réanimation</span> pendant <span class=\"kw-chiffre\">24–48 h</span> — <span class=\"kw-bio\">fonction rénale</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">calcium ionisé</span>, <span class=\"kw-bio\">ECG quotidien</span>.<br><strong>HPT primaire non opérée :</strong> <span class=\"kw-clinique\">surveillance simple</span> si asymptomatique (<span class=\"kw-bio\">calcémie</span>, fonction rénale, retentissement osseux).<br><strong>Complications chroniques à dépister :</strong> <span class=\"kw-alerte\">néphrocalcinose</span>, <span class=\"kw-alerte\">lithiases récidivantes</span>, <span class=\"kw-alerte\">insuffisance rénale</span>, <span class=\"kw-alerte\">calcifications ectopiques</span> (coronaires, valves).</p>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique8","label":"Collège CUEN — Calcémie / Hypercalcémie"},{"href":"https://www.sfendocrino.org/item-268-hypercalcemie/","label":"Collège endocrinologie — Item 268 Hypercalcémie"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hypercalcémie confirmée — Confirmer (calcium ionisé / albuminémie), évaluer la gravité, puis orienter par la PTH","detail":"<h4>CAT — hypercalcémie — Triage de gravité, puis orientation étiologique par la <span class=\"kw-bio\">PTH</span></h4>","branches":[{"to":"t-urgence","label":"Sévère / symptomatique : Ca > 3,5 mmol/L, ou > 3 mmol/L avec signes de mauvaise tolérance","color":"red"},{"to":"q-pth","label":"Modérée / asymptomatique (< 3 mmol/L) → doser la PTH","color":"amber"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence thérapeutique — hypercalcémie aiguë sévère","color":"red","detail":"<h4>Gravité</h4><ul><li><span class=\"kw-alerte\">Ca &gt; 3,5 mmol/L</span>, ou <span class=\"kw-chiffre\">&gt; 3 mmol/L</span> avec <span class=\"kw-alerte\">signes de mauvaise tolérance</span></li><li>Risque de <span class=\"kw-alerte\">décès par trouble du rythme cardiaque</span></li></ul><h4>Mesures immédiates</h4><ul><li>Arrêt des <span class=\"kw-ttt\">hypercalcémiants</span> (<span class=\"kw-ttt\">calcium</span>, <span class=\"kw-ttt\">vitamine D</span>, <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">thiazidiques</span>) et des <span class=\"kw-ci\">digitaliques</span></li><li><span class=\"kw-ttt\">Réhydratation</span> par <span class=\"kw-ttt\">sérum salé isotonique 0,9 %</span> : <span class=\"kw-chiffre\">1 L la 1ʳᵉ heure puis 2–4 L/24 h</span> (effet <span class=\"kw-clinique\">pro-calciuriant</span>)</li></ul><h4>Selon le mécanisme</h4><ul><li><span class=\"kw-ttt\">Bisphosphonates</span> (effet dès <span class=\"kw-chiffre\">48 h</span>) ± <span class=\"kw-ttt\">dénosumab</span> si échec / CI</li><li><span class=\"kw-ttt\">Glucocorticoïdes</span> : myélome, hémopathies, granulomatoses</li><li><span class=\"kw-ttt\">Cinacalcet</span> : <span class=\"kw-etio\">carcinome parathyroïdien</span></li><li><span class=\"kw-ttt\">Épuration extra-rénale</span> (bain pauvre en calcium) : forme grave avec <span class=\"kw-clinique\">insuffisance rénale</span> — effet rapide</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">USC / réanimation</span> <span class=\"kw-chiffre\">24–48 h</span> : <span class=\"kw-bio\">fonction rénale</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">calcium ionisé</span>, <span class=\"kw-bio\">ECG quotidien</span></li></ul>"},{"id":"q-pth","kind":"decision","label":"PTH : élevée / inadaptée, ou basse / freinée ? — La PTH dichotomise l’arbre étiologique (normalement freinée en cas d’hypercalcémie)","branches":[{"to":"q-calciurie","label":"PTH élevée ou inadaptée (normale)","color":"amber"},{"to":"q-freinee","label":"PTH basse / freinée (adaptée)","color":"amber"}]},{"id":"q-calciurie","kind":"decision","label":"Calciurie ? — Distingue l’hyperparathyroïdie primaire de l’hypercalcémie-hypocalciurie familiale","branches":[{"to":"t-hpt","label":"Calciurie élevée","color":"amber"},{"to":"t-hhf","label":"Calciurie basse","color":"blue"}]},{"id":"t-hpt","kind":"terminal","label":"Hyperparathyroïdie primaire (± tertiaire, lithium)","color":"amber","detail":"<h4>Repères</h4><ul><li><span class=\"kw-etio\">Cause n° 1</span> : <span class=\"kw-chiffre\">55–60 %</span> des hypercalcémies</li><li>Endocrinopathie de la <span class=\"kw-clinique\">femme ménopausée</span> (<span class=\"kw-chiffre\">50–60 ans</span>)</li><li><span class=\"kw-clinique\">Asymptomatique dans 80–90 %</span> des cas</li></ul><h4>Biologie</h4><ul><li>Hypercalcémie + <span class=\"kw-clinique\">PTH inadaptée</span> (élevée ou normale) ; <span class=\"kw-bio\">hypophosphatémie</span> ; <span class=\"kw-bio\">hypercalciurie</span> ; <span class=\"kw-bio\">hypercalcitriolémie</span></li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Adénome unique</span> (≈<span class=\"kw-chiffre\"> 80 %</span>)</li><li><span class=\"kw-etio\">Hyperplasie des 4 glandes</span> (<span class=\"kw-chiffre\">10–15 %</span> — penser <span class=\"kw-clinique\">NEM 1 / NEM 2</span> si sujet jeune ou familial)</li><li><span class=\"kw-etio\">Carcinome parathyroïdien</span> (&lt;<span class=\"kw-chiffre\"> 2 %</span>, hypercalcémie sévère)</li><li><span class=\"kw-etio\">HPT tertiaire</span> (<span class=\"kw-ci\">insuffisance rénale</span> chronique), <span class=\"kw-etio\">lithium</span> → même tableau <span class=\"kw-ttt\">biologique</span></li></ul><h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li>Indiquée si forme symptomatique, <span class=\"kw-chiffre\">âge &lt; 50 ans</span>, Ca <span class=\"kw-chiffre\">&gt; 2,75 mmol/L</span> ou calciurie <span class=\"kw-chiffre\">&gt; 10 mmol/24 h</span>, <span class=\"kw-ci\">insuffisance rénale</span> attribuable, ou atteinte osseuse (<span class=\"kw-chiffre\">T-score &lt; −2,5</span>)</li></ul>"},{"id":"t-hhf","kind":"terminal","label":"Hypercalcémie-hypocalciurie familiale bénigne (à distinguer)","color":"blue","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Affection <span class=\"kw-etio\">héréditaire</span> <span class=\"kw-def\">autosomique dominante</span>, généralement <span class=\"kw-clinique\">asymptomatique</span> ; mutation inactivatrice du <span class=\"kw-def\">CaSR</span></li></ul><h4>Piège <span class=\"kw-ttt\">biologique</span></h4><ul><li>Tableau <span class=\"kw-ttt\">biologique</span> d’<span class=\"kw-etio\">hyperparathyroïdie primaire</span> <strong>sauf la calciurie BASSE</strong></li></ul><h4>Intérêt</h4><ul><li>À distinguer de l’HPT primaire pour <span class=\"kw-ci\">éviter une chirurgie inutile</span></li></ul>"},{"id":"q-freinee","kind":"decision","label":"Orientation devant une PTH freinée ? — Contexte clinique, phosphatémie et calcitriol orientent la cause","branches":[{"to":"t-cancer","label":"Contexte néoplasique : métastases, myélome, PTHrp (calcitriol bas)","color":"red"},{"to":"t-autres","label":"Calcitriol élevé ou autre cause : granulomatose, hypervitaminose, endocrinien, médicament, immobilisation","color":"amber"}]},{"id":"t-cancer","kind":"terminal","label":"Hypercalcémies malignes","color":"red","detail":"<h4>Mécanismes</h4><ul><li><span class=\"kw-etio\">Métastases osseuses ostéolytiques</span> — PPRST : prostate, poumon, rein, sein, thyroïde</li><li><span class=\"kw-etio\">Myélome multiple</span> (Osteoclast Activating Factor), lymphomes, leucémies</li><li><span class=\"kw-etio\">Hypercalcémie humorale maligne</span> : <span class=\"kw-def\">PTHrp</span> <span class=\"kw-etio\">paranéoplasique</span> (<span class=\"kw-clinique\">carcinome</span> pulmonaire non à petites cellules, LNH à cellules T)</li></ul><h4>Signature <span class=\"kw-ttt\">biologique</span></h4><ul><li><span class=\"kw-clinique\">PTH effondrée</span> ; dans l’HHM : <span class=\"kw-bio\">phosphate basse</span> et <span class=\"kw-bio\">calcitriol bas</span> (la PTHrp n’active pas la 1α-hydroxylase)</li></ul><h4>Examens</h4><ul><li><span class=\"kw-bio\">NFS, CRP</span>, <span class=\"kw-bio\">EPS / EPU</span>, <span class=\"kw-bio\">protéinurie</span> ; <span class=\"kw-imagerie\">radiographie de thorax</span> ; <span class=\"kw-bio\">PTHrp</span> si hypophosphatémie associée</li></ul>"},{"id":"t-autres","kind":"terminal","label":"Causes à PTH freinée non malignes","color":"amber","detail":"<h4>Granulomatoses</h4><ul><li>1α-hydroxylase non régulée → ↑ <span class=\"kw-bio\">calcitriol</span> : <span class=\"kw-etio\">sarcoïdose</span> (<span class=\"kw-chiffre\">10–20 %</span>), <span class=\"kw-etio\">tuberculose</span> ++, lèpre, histoplasmose</li></ul><h4>Médicaments</h4><ul><li><span class=\"kw-etio\">Hypervitaminose D</span> ; <span class=\"kw-etio\">hypervitaminose A</span> (<span class=\"kw-ttt\">rétinoïdes</span>, &gt; 50 <span class=\"kw-chiffre\">000 UI</span>/j) ; <span class=\"kw-ttt\">thiazidiques</span> ; <span class=\"kw-ttt\">tériparatide</span></li></ul><h4>Endocriniennes</h4><ul><li><span class=\"kw-etio\">Hyperthyroïdie</span> (<span class=\"kw-chiffre\">15–20 %</span>), <span class=\"kw-etio\">insuffisance surrénalienne aiguë</span>, <span class=\"kw-etio\">phéochromocytome</span> (après ablation), <span class=\"kw-etio\">acromégalie</span></li></ul><h4>Autres</h4><ul><li><span class=\"kw-etio\">Syndrome des buveurs de lait</span> / excès de supplémentation calcique (surtout si <span class=\"kw-ci\">insuffisance rénale</span>) ; <span class=\"kw-etio\">immobilisation prolongée</span></li></ul><h4>Examens</h4><ul><li><span class=\"kw-bio\">TSHus</span>, <span class=\"kw-bio\">enzyme de conversion de l’angiotensine</span> ; <span class=\"kw-bio\">25-OH-vitamine D</span> et <span class=\"kw-bio\">calcitriol</span></li></ul>"}]},"cards":[{"i":"12bc4423a0b8","n":268,"o":"268-1","u":"Définition","t":"Connaître les normes de la calcémie totale et de la calcémie ionisée","q":"Quelle est la composition des différentes fractions de la calcémie totale ?","a":"<ul><li><strong>Calcium ionisé</strong> : 50 à 55%, fraction métaboliquement active.</li><li><strong>Calcium lié aux protéines</strong> : environ 40%, principalement à l'<strong>albumine</strong>.</li><li><strong>Calcium complexé aux anions</strong> : 5 à 10%, lié aux citrates, phosphates, bicarbonates.</li></ul>"},{"i":"44f587cc1357","n":268,"o":"268-1","u":"Définition","t":"Connaître les normes de la calcémie totale et de la calcémie ionisée","q":"Quels sont les facteurs principaux qui peuvent faire varier la calcémie ionisée ?","a":"<ul><li>Le <strong>pH sanguin</strong> : l'<strong>acidose</strong> augmente la calcémie ionisée (en diminuant la fraction liée à l'albumine), tandis que l'<strong>alcalose</strong> la diminue (en augmentant la fraction liée à l'albumine).</li><li>Les conditions de <strong>prélèvement et de conservation</strong> sont cruciales pour le dosage de référence : seringue à gaz du sang, envoi immédiat à 4°C.</li></ul>"},{"i":"51cb6567090a","n":268,"o":"268-1","u":"Définition","t":"Connaître les normes de la calcémie totale et de la calcémie ionisée","q":"Le pH sanguin modifie-t-il la calcémie totale ?","a":"<p>Non, le pH sanguin ne modifie <strong>PAS</strong> la calcémie totale, seulement la répartition entre les fractions ionisée et liée aux protéines.</p>"},{"i":"982cceb632d5","n":268,"o":"268-1","u":"Définition","t":"Connaître les normes de la calcémie totale et de la calcémie ionisée","q":"Quelles sont les valeurs normales de la calcémie totale plasmatique chez l'adulte ?","a":"<p>La calcémie totale normale est comprise entre <strong>2,20</strong> et <strong>2,60 mmol/L</strong>, ce qui correspond à environ 105 mg/L.</p>"},{"i":"d88d38b9f219","n":268,"o":"268-1","u":"Définition","t":"Connaître les normes de la calcémie totale et de la calcémie ionisée","q":"Quelle est la particularité métabolique de la fraction ionisée du calcium par rapport à la calcémie totale ?","a":"<p>Le <strong>calcium ionisé</strong> est la seule fraction <strong>métaboliquement active</strong> et la seule variable régulée. Il représente 50 à 55% de la calcémie totale et constitue le dosage de référence.</p>"},{"i":"d8ba5462265b","n":268,"o":"268-1","u":"Définition","t":"Connaître les normes de la calcémie totale et de la calcémie ionisée","q":"Quelles sont les valeurs normales de la calcémie ionisée plasmatique chez l'adulte ?","a":"<p>La calcémie ionisée normale est comprise entre <strong>1,15</strong> et <strong>1,35 mmol/L</strong>.</p>"},{"i":"347a20bb299a","n":268,"o":"268-2","u":"Diagnostic positif","t":"Identifier une hypercalcémie","q":"Quelle est la formule de correction de la calcémie totale en fonction de l'albuminémie et dans quel contexte est-elle utile ?","a":"<p>La formule de correction de la calcémie en fonction de l'albuminémie est :</p><ul><li><strong>Ca corrigée (mmol/L) = Ca total mesuré + [(40 − albuminémie) × 0,025]</strong></li></ul><p>(L'albuminémie est en g/L, et la valeur de référence est 40 g/L).</p><p>Cette correction est utile car une <strong>hypoalbuminémie</strong> peut masquer une hypercalcémie vraie, tandis qu'une hyperalbuminémie peut simuler une hypercalcémie en augmentant la fraction liée aux protéines.</p>"},{"i":"405bd67a680b","n":268,"o":"268-2","u":"Diagnostic positif","t":"Identifier une hypercalcémie","q":"Qu'est-ce qu'une hypercalcémie vraie et en quoi diffère-t-elle d'une fausse hypercalcémie ?","a":"<p>Une <strong>hypercalcémie vraie</strong> correspond à une élévation du <strong>calcium ionisé</strong>, qui est la seule variable régulée et biologiquement active.</p><p>Une <strong>fausse hypercalcémie</strong> est une augmentation de la fraction du calcium liée aux protéines (principalement l'albumine), sans élévation du calcium ionisé. Elle survient typiquement en cas d'<strong>hyperalbuminémie</strong> (par exemple, en cas de déshydratation), où la calcémie totale est augmentée mais le calcium ionisé reste normal.</p>"},{"i":"471e63abf870","n":268,"o":"268-2","u":"Diagnostic positif","t":"Identifier une hypercalcémie","q":"Comment définit-on biologiquement une hypercalcémie, en mentionnant les seuils pour la calcémie totale et la calcémie ionisée ?","a":"<p>Une hypercalcémie se définit biologiquement par :</p><ul><li>Une calcémie totale (corrigée si besoin) <strong>&gt; 2,60 mmol/L</strong>. En contexte d'urgence, on retient &gt; 2,55 mmol/L.</li><li>Une calcémie ionisée <strong>&gt; 1,35 mmol/L</strong>. En contexte d'urgence, on retient &gt; 1,30 mmol/L.</li></ul>"},{"i":"c474fabbbc53","n":268,"o":"268-2","u":"Diagnostic positif","t":"Identifier une hypercalcémie","q":"Quels dosages biologiques sont indispensables pour tout bilan d'hypercalcémie ?","a":"<p>Tout bilan d'hypercalcémie doit comporter un dosage du <strong>calcium ionisé</strong> et/ou un dosage de l'<strong>albumine</strong> (avec éventuellement le pH sanguin pour ajuster le calcium ionisé) afin d'évaluer la fraction biologiquement active du calcium et de différencier une hypercalcémie vraie d'une fausse hypercalcémie.</p>"},{"i":"021175380f03","n":268,"o":"268-4","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques associés à l'hypercalcémie","q":"Quels sont les principaux signes cliniques de l'hypercalcémie chronique ?","a":"<p>L'hypercalcémie chronique peut entraîner les signes cliniques suivants :</p><ul><li><strong>Signes généraux</strong> : asthénie physique/psychique, amaigrissement, anorexie.</li><li><strong>Signes digestifs</strong> : épigastralgies, nausées, vomissements (parfois incoercibles), constipation.</li><li><strong>Signes rénaux</strong> : <strong>syndrome polyuro-polydipsique</strong> (diabète insipide néphrogénique), <strong>néphrocalcinose</strong> conduisant à une insuffisance rénale chronique (IRC), <strong>lithiases rénales</strong> (phosphate/oxalate de calcium), souvent bilatérales et récidivantes.</li><li><strong>Signes neurologiques</strong> : céphalées, syndrome « pseudo-polynévritique » (hypo/aréflexie), allure « pseudo-myopathique », troubles cognitifs et de la mémoire.</li><li><strong>Signes psychiatriques</strong> : troubles de l'humeur, dépression/anxiété, épisodes hallucinatoires ou psychotiques.</li><li><strong>Signes cardiovasculaires</strong> : HTA, anomalies ECG, calcifications ectopiques (coronaires, valves, fibres myocardiques).</li></ul>"},{"i":"b3e032478cc0","n":268,"o":"268-4","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques associés à l'hypercalcémie","q":"Quels sont les principaux signes cliniques de l'hypercalcémie aiguë sévère ('crise aiguë hypercalcémique') ?","a":"<p>L'hypercalcémie aiguë sévère est une <strong>urgence médicale</strong> avec risque de décès. Ses signes cliniques incluent :</p><ul><li><strong>Signes généraux</strong> : fièvre, asthénie, anorexie.</li><li><strong>Signes digestifs</strong> : douleurs abdominales (parfois pseudo-chirurgicales), <strong>constipation</strong>, nausées, vomissements, rares pancréatites aiguës.</li><li><strong>Signes neurologiques</strong> : <strong>troubles de la vigilance</strong> (du syndrome confusionnel au coma), déficits cognitifs, troubles de l'humeur, épisodes hallucinatoires/psychotiques.</li><li><strong>Signes rénaux</strong> : déshydratation inexpliquée (par perte rénale de Na et d'eau), <strong>syndrome polyuro-polydipsique</strong> (diabète insipide néphrogénique), déshydratation extracellulaire (DEC) avec possible insuffisance rénale aiguë (IRA) fonctionnelle.</li><li><strong>Signes cardiovasculaires</strong> : HTA ou hypotension si déshydratation majeure, anomalies ECG, et surtout <strong>troubles du rythme</strong> (extrasystoles ventriculaires, tachycardie ventriculaire, fibrillation ventriculaire) si calcémie &gt; <strong>3,5–4 mmol/L</strong>.</li></ul>"},{"i":"d585b9f42ee5","n":268,"o":"268-4","u":"Diagnostic positif","t":"Connaître les principaux signes cliniques associés à l'hypercalcémie","q":"Comment l'expression clinique de l'hypercalcémie varie-t-elle ?","a":"<p>L'expression clinique de l'hypercalcémie est <strong>très variable</strong> et dépend principalement de la <strong>sévérité</strong> et de la <strong>rapidité d'installation</strong> de l'hypercalcémie. Une part importante des hypercalcémies peut être <strong>asymptomatique</strong>.</p>"},{"i":"1c60152f1b1a","n":268,"o":"268-6","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention à réaliser en fonction du contexte devant une hypercalcémie","q":"Quels sont les examens complémentaires de première intention pour confirmer le diagnostic positif d'une hypercalcémie ?","a":"<p>Pour confirmer le diagnostic d'hypercalcémie, il est nécessaire de doser :</p><ul><li>Le <strong>calcium total</strong>.</li><li>Le <strong>calcium ionisé</strong> et/ou l'<strong>albuminémie</strong> (avec un ajustement éventuel selon le pH sanguin pour le calcium ionisé).</li></ul>"},{"i":"396d98b9b970","n":268,"o":"268-6","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention à réaliser en fonction du contexte devant une hypercalcémie","q":"Quels autres examens complémentaires de première intention peuvent aider à l'orientation étiologique d'une hypercalcémie, en dehors de la PTH ?","a":"<p>En dehors de la PTH, d'autres examens de première intention pour l'orientation étiologique d'une hypercalcémie sont :</p><ul><li>Le <strong>phosphate sérique</strong> (bas dans l'hyperparathyroïdie primaire et l'hypercalcémie humorale maligne).</li><li>La <strong>vitamine D</strong> (mesure de la <strong>25-OH-vitamine D</strong> et de la <strong>calcitriolémie (1,25-OH-vitamine D)</strong>).</li><li>La <strong>calciurie</strong> (à jeun et des 24h).</li><li>L'<strong>électrophorèse des protéines plasmatiques (EPP)</strong>, qui est systématique selon le Collège de néphrologie.</li></ul>"},{"i":"984e6a44db9a","n":268,"o":"268-6","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention à réaliser en fonction du contexte devant une hypercalcémie","q":"Quels sont les examens complémentaires de première intention pour évaluer la gravité d'une hypercalcémie ?","a":"<p>L'évaluation de la gravité d'une hypercalcémie repose sur :</p><ul><li>La <strong>créatinine</strong>.</li><li>L'<strong>ionogramme sanguin</strong>.</li><li>Un <strong>ECG</strong> (électrocardiogramme), qui est systématique devant une hypercalcémie sévère (<strong>> 3 mmol/L</strong>).</li></ul>"},{"i":"c2c8cc37ff6c","n":268,"o":"268-6","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention à réaliser en fonction du contexte devant une hypercalcémie","q":"Quel est l'examen complémentaire de première intention, central pour l'orientation étiologique d'une hypercalcémie, et quelle est sa logique d'interprétation ?","a":"<p>L'examen central pour l'orientation étiologique est la <strong>PTH plasmatique</strong>. Sa logique d'interprétation est dichotomique :</p><ul><li>Si la <strong>PTH est élevée ou inadaptée</strong>, cela oriente vers une hyperparathyroïdie et pathologies apparentées.</li><li>Si la <strong>PTH est basse ou freinée</strong>, cela oriente vers les cancers, granulomatoses ou intoxications.</li></ul>"},{"i":"1c7ff6478e8e","n":268,"o":"268-8","u":"Étiologies","t":"Connaître les principales étiologies des hypercalcémies (arbre diagnostique)","q":"Quels sont les repères cliniques et biologiques clés d'une hyperparathyroïdie primaire ?","a":"<ul><li><strong>Terrain</strong> : endocrinopathie fréquente de la <strong>femme ménopausée</strong> (50-60 ans).</li><li><strong>Clinique</strong> : <strong>asymptomatique</strong> dans 80-90% des cas ; sinon, manifestations d'hypercalcémie (lithiases, néphrocalcinose) ou osseuses (ostéoporose).</li><li><strong>Biologie</strong> : <strong>hypercalcémie</strong> associée à une <strong>PTH élevée ou normale</strong> (inadaptée), une <strong>hypophosphatémie</strong> (2/3 des cas) et une hypercalcitriolémie.</li></ul>"},{"i":"3a692e26c2b2","n":268,"o":"268-8","u":"Étiologies","t":"Connaître les principales étiologies des hypercalcémies (arbre diagnostique)","q":"Dans le cadre d'une hypercalcémie à PTH basse/freinée, quelles sont les causes néoplasiques les plus fréquentes ?","a":"<ul><li>Les <strong>métastases osseuses ostéolytiques</strong>, notamment issues du sein, du poumon, du rein, de la thyroïde et de la prostate (PPRST).</li><li>Le <strong>myélome multiple</strong> via la sécrétion d'Osteoclast Activating Factor.</li><li>L'<strong>hypercalcémie humorale maligne</strong> par sécrétion paranéoplasique de PTHrp, notamment dans certains carcinomes pulmonaires et lymphomes, avec une PTH effondrée et un calcitriol bas.</li></ul>"},{"i":"5be1c968b42a","n":268,"o":"268-8","u":"Étiologies","t":"Connaître les principales étiologies des hypercalcémies (arbre diagnostique)","q":"Quelle est l'approche diagnostique initiale d'une hypercalcémie concernant la Parathormone (PTH) ?","a":"<p>La première orientation diagnostique pour une hypercalcémie est de doser la <strong>PTH</strong> afin de la classer en hypercalcémies à <strong>PTH élevée/inappropriée</strong> ou à <strong>PTH basse/freinée</strong>.</p>"},{"i":"70e58fc271b6","n":268,"o":"268-8","u":"Étiologies","t":"Connaître les principales étiologies des hypercalcémies (arbre diagnostique)","q":"Quelles sont les causes endocriniennes et les maladies granulomateuses pouvant entraîner une hypercalcémie à PTH basse/freinée ?","a":"<ul><li><strong>Endocriniennes</strong> : L'<strong>hyperthyroïdie</strong> (15-20% des cas), l'insuffisance surrénalienne aiguë, le phéochromocytome et l'acromégalie.</li><li><strong>Granulomatoses</strong> : La <strong>sarcoïdose</strong> (10-20% des cas) et la <strong>tuberculose</strong> sont les plus fréquentes, en raison d'une production non régulée de 1α-hydroxylase augmentant le calcitriol.</li></ul>"},{"i":"75c1be9645e7","n":268,"o":"268-8","u":"Étiologies","t":"Connaître les principales étiologies des hypercalcémies (arbre diagnostique)","q":"Quels sont les médicaments susceptibles d'induire une hypercalcémie à PTH basse/freinée ?","a":"<ul><li>L'<strong>hypervitaminose D</strong> ou l'<strong>hypervitaminose A</strong> (rétinoïdes).</li><li>Les <strong>diurétiques thiazidiques</strong>.</li><li>La <strong>tériparatide</strong>.</li></ul>"},{"i":"9ddb446e3781","n":268,"o":"268-8","u":"Étiologies","t":"Connaître les principales étiologies des hypercalcémies (arbre diagnostique)","q":"Quelles sont les deux principales causes d'hypercalcémie à PTH élevée/inappropriée ?","a":"<ul><li>L'<strong>hyperparathyroïdie primaire</strong>, qui est la cause n°1, représentant 55-60% des hypercalcémies.</li><li>L'<strong>hypercalcémie-hypocalciurie familiale bénigne</strong>, une maladie autosomique dominante généralement asymptomatique avec une calciurie basse caractéristique.</li></ul>"},{"i":"490dabb53f8b","n":268,"o":"268-9","u":"Prise en charge","t":"Connaître les principes du traitement des hypercalcémies sévères","q":"Quels sont les traitements qui ne sont plus recommandés dans la prise en charge de l'hypercalcémie aiguë sévère ?","a":"<ul><li>La <strong>calcitonine</strong>, en raison de son effet trop transitoire.</li><li>La <strong>diurèse forcée au furosémide</strong>, qui est déconseillée (notamment en cas de myélome). Elle peut éventuellement être envisagée après réhydratation pour maintenir la diurèse en cas d'insuffisance rénale aiguë fonctionnelle ou d'insuffisance cardiaque.</li></ul>"},{"i":"5f2e4e73ca7e","n":268,"o":"268-9","u":"Prise en charge","t":"Connaître les principes du traitement des hypercalcémies sévères","q":"Dans quelles situations particulières l'épuration extra-rénale est-elle indiquée pour une hypercalcémie aiguë sévère ?","a":"<p>L'<strong>épuration extra-rénale</strong> (dialyse avec bain pauvre en calcium) est indiquée dans les formes graves, particulièrement en cas d'<strong>insuffisance rénale</strong>, en raison de son <strong>effet rapide</strong> sur la calcémie.</p>"},{"i":"615bfeccbb4f","n":268,"o":"268-9","u":"Prise en charge","t":"Connaître les principes du traitement des hypercalcémies sévères","q":"Quels sont les objectifs initiaux de la prise en charge d'une hypercalcémie aiguë sévère ?","a":"<p>Les objectifs initiaux sont de <strong>faire baisser rapidement la calcémie</strong> et, en parallèle, d'instaurer un <strong>traitement étiologique</strong>. Une surveillance est nécessaire en <strong>USC/réanimation</strong> pendant 24 à 48 heures pour monitorer la fonction rénale, l'ionogramme, le calcium ionisé et l'ECG.</p>"},{"i":"688865450172","n":268,"o":"268-9","u":"Prise en charge","t":"Connaître les principes du traitement des hypercalcémies sévères","q":"Quels sont les traitements spécifiques à cibler en fonction du mécanisme de l'hypercalcémie aiguë sévère ?","a":"<ul><li>Pour diminuer la résorption osseuse : <strong>bisphosphonates</strong> (effet retardé, dès 48h) ; <strong>dénosumab</strong> si échec ou contre-indication, notamment en cas d'hypercalcémie maligne ou d'hyperparathyroïdie primaire.</li><li>Pour diminuer l'absorption digestive : <strong>glucocorticoïdes</strong> (prednisone 10-20 mg/j) en cas de myélome, hémopathies (lymphome) ou granulomatoses (sarcoïdose).</li><li>Spécifique à l'hypercalcémie sévère du carcinome parathyroïdien : <strong>cinacalcet</strong> (calcimimétique).</li></ul>"},{"i":"dc4ce2e1b9cf","n":268,"o":"268-9","u":"Prise en charge","t":"Connaître les principes du traitement des hypercalcémies sévères","q":"Comment définir une hypercalcémie aiguë sévère et quel est son niveau d'urgence ?","a":"<p>Une hypercalcémie aiguë est considérée comme <strong>sévère et symptomatique</strong> si la calcémie est <strong>supérieure à 3 mmol/L</strong>. Il s'agit d'une <strong>urgence thérapeutique</strong>.</p>"},{"i":"dc5e30265954","n":268,"o":"268-9","u":"Prise en charge","t":"Connaître les principes du traitement des hypercalcémies sévères","q":"Quel est le traitement de première intention pour corriger l'hypercalcémie aiguë sévère et quel est son mécanisme d'action ?","a":"<p>Le traitement de première intention est la <strong>réhydratation par sérum salé isotonique 0,9 %</strong> (par exemple, 1 L la 1<sup>ère</sup> heure puis 2-4 L/24h). Ce traitement corrige la déshydratation extra-cellulaire (DEC) et exerce un <strong>effet pro-calciuriant</strong> en diminuant la réabsorption rénale du calcium via la réplétion volémique.</p>"},{"i":"ec6ab706ff11","n":268,"o":"268-9","u":"Prise en charge","t":"Connaître les principes du traitement des hypercalcémies sévères","q":"Quels sont les traitements médicamenteux à risque à arrêter immédiatement lors d'une hypercalcémie aiguë sévère ?","a":"<ul><li>Les traitements hypercalcémiants : <strong>calcium, vitamine D, lithium, diurétiques thiazidiques</strong>.</li><li>Les traitements aggravant la déshydratation : <strong>diurétiques, néphrotoxiques</strong>.</li><li>Les traitements aggravant la toxicité cardiaque : <strong>digitaliques, hypokaliémiants</strong>.</li></ul>"}]};